    #[verifier::type_invariant]
    spec fn wf_read_handle(self) -> bool {
        equal(self.handle@.instance_id(), self.rwlock.inst@.id())
            && self.rwlock.wf()
    }

    pub closed spec fn view(self) -> V {
        self.handle@.element()
    }

